import{z as l,x as s,o as e,c as d,q as r,j as t,D as a,d as B,s as o,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"自由银行时代","description":"","frontmatter":{"title":"自由银行时代","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mh-free-banking.md","filePath":"econ/mh-free-banking.md","lastUpdated":1791063341000}'),C={name:"econ/mh-free-banking.md"};function p(m,E,h,D,c,f){const n=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="自由银行时代" tabindex="-1">自由银行时代 <a class="header-anchor" href="#自由银行时代" aria-label="Permalink to &quot;自由银行时代&quot;">​</a></h1><div class="epigraph"><p>银行券的纪律不在发钞者的誓言里，而在持有人每天把它送回柜台兑现的那个动作里；没有回兑，誓言只是印刷品。</p><footer>—— 据 Selgin, The Theory of Free Banking, 1988；Rolnick and Weber 1983 整理</footer></div><p><a href="/econ/mh-commodity-money">上一课</a>把金属本位的胜出写成套利压出的结果：国家认证面额，交易按面额走。缺口随即出现：银行把自己发行的券放进流通，承诺随时兑回金属——这套私人的面额承诺凭什么被人按平价收下？19 世纪的「自由银行」实验给了几组对照样本。本课程考察发钞的纪律如何自下而上地长出来，又在哪里失效。挤兑的微观理论已由<a href="/econ/diamond-dybvig">Diamond–Dybvig 挤兑</a>给出；本课看它在没有央行兜底的年代如何被制度性压制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>银行券是银行的即期负债，持有人可按面额兑金银。竞争发钞的核心问题是纪律：过发的银行券会回流到发行行兑现，储备耗尽即破产；但每家银行都希望别家节制、自己多发。缺口是找到一种安排，让「过发」在变成危机之前就被价格或清算机制惩罚。</p><p><span class="marginnote">术语翻译：银行券就是银行自己印的「欠条」，「即期负债」意思是持有人今天拿来、银行今天就得付金银，不能拖欠。所以过发欠条等于给自己埋雷——欠条流出去多少，理论上就有多少可以随时涌回柜台要钱，储备一空即破产。</span></p><p>纪律的候选答案有三种：持有人逐笔回兑、同业清算网络、以及合同条款本身。三者分别对应三种成本：持有人的检验成本、清算的运营成本、以及条款对挤兑的处理能力。没有央行、没有存款保险的年代，这三条线就是全部防线。</p><h3 id="三组样本" tabindex="-1">三组样本 <a class="header-anchor" href="#三组样本" aria-label="Permalink to &quot;三组样本&quot;">​</a></h3><p>苏格兰（1716–1845）：几家大银行竞争发钞，票据每天交换、按面额清算，Adam Smith 记述其稳健。美国 1837–1863：州立法下进入自由，但银行券须以州债券存押于州审计官，所谓「自由」是进入自由而非无约束。加拿大：特许银行分支制，破产极少。</p><p><span class="marginnote">苏格兰银行 1730–1765 年使用「期权条款」：银行可把兑付推迟六个月，逾期按年息 5% 计息。它把挤兑的时点成本写进合同，让只有真流动性担忧的人才提前回兑；1765 年被议会禁掉，Smith 在 1776 年已记述其运作。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把「券为什么按面额值钱」写成一道逐日套利。设券面额为 \\(1\\)，市场折价为 \\(\\delta\\)，回兑成本为 \\(c\\)。只要 \\(\\delta \\gt c\\)，套利者收券、送兑、赚取差价，折价被压回 \\(c\\) 以内。清算网络把 \\(c\\) 压到接近零：波士顿的 Suffolk 系统（1825 年起）把乡村银行券集中交换，逼发行行备足金属，否则直接拒绝其券进入网络——平价从法令问题变成网络准入问题。</p><p><span class="marginnote">数字实例：某州银行券市价 0.97，回兑的运费与工钱合计约 1 分，即 \\(c=0.01\\)。套利者花 97 分收券、送柜台兑回 100 分金属，每张净赚约 2 分；只要差价还在，收券送兑的人络绎不绝，折价就被压回 1 分以内——平价不必法令维持，利润动机自己干活。</span></p><p>失败案例同样要写成机制。美国「野猫银行」的传统叙事说银行故意远遁荒野逃避兑付；Rolnick 与 Weber 重检数据后发现，印第安纳、明尼苏达等州的银行失败主要由存押债券跌价驱动——银行券充足率没问题，是担保品没了。担保品机制比「跑路」解释了更多破产。</p>',14)),(e(),t(i,null,{default:a(()=>[o(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOTE%5B%22%E9%93%B6%E8%A1%8C%E5%8F%91%E8%A1%8C%E5%8D%B3%E6%9C%9F%E5%85%91%E4%BB%98%E5%88%B8%22%5D%20--%3E%20DISC%7B%22%E5%B8%82%E5%9C%BA%E6%8A%98%E4%BB%B7%20%CE%B4%20%E9%AB%98%E4%BA%8E%E5%9B%9E%E5%85%91%E6%88%90%E6%9C%AC%3F%22%7D%0A%20%20DISC%20--%3E%7C%E6%98%AF%7C%20ARB%5B%22%E5%A5%97%E5%88%A9%E6%94%B6%E5%88%B8%E9%80%81%E5%85%91%22%5D%0A%20%20ARB%20--%3E%20NET%5B%22%E5%90%8C%E4%B8%9A%E6%B8%85%E7%AE%97%E7%BD%91%E7%BB%9C%E9%9B%86%E4%B8%AD%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20NET%20--%3E%20PAR%5B%22%E5%B9%B3%E4%BB%B7%E6%88%90%E7%AB%8B%EF%BC%8C%E8%BF%87%E5%8F%91%E8%A2%AB%E6%83%A9%E7%BD%9A%22%5D%0A%20%20DISC%20--%3E%7C%E5%90%A6%7C%20HOLD%5B%22%E6%8A%98%E4%BB%B7%E6%8C%81%E7%BB%AD%EF%BC%8C%E5%88%B8%E4%BB%B7%E6%98%BE%E7%A4%BA%E4%BF%A1%E7%94%A8%22%5D%0A%20%20NET%20--%3E%20RUN%5B%22%E9%9B%86%E4%B8%AD%E6%8C%A4%E5%85%91%EF%BC%9A%E5%81%9C%E5%85%91%E9%98%80%E9%97%A8%22%5D%0A%20%20RUN%20--%3E%20OPT%5B%22%E6%9C%9F%E6%9D%83%E6%9D%A1%E6%AC%BE%E6%88%96%E6%9A%82%E5%81%9C%E5%85%91%E4%BB%98%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"机制是折价作为信用利差的实时显示：一张券的市价就是发行行的违约概率乘以损失率，清算网络让这个信号每天被发现并执行。它不依赖任何人对银行的善意，也不需要央行设定利率。三个层次咬合：持有人回兑是边缘约束，清算网络是批量执行，停兑是最后阀门——1837 与 1857 年美国两度全面停兑，说明前两层在系统性的金属外流面前确实会失守。",-1)),(e(),t(i,null,{default:a(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E9%87%91%E5%B1%9E%E5%A4%96%E6%B5%81%3A%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%86%B2%E5%87%BB%22%5D%20--%3E%20L1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%3A%20%E6%8C%81%E6%9C%89%E4%BA%BA%E9%80%90%E7%AC%94%E5%9B%9E%E5%85%91%22%5D%0A%20%20L1%20--%3E%7C%22%E5%8E%8B%E5%8A%9B%E5%88%86%E6%95%A3%22%7C%20ABS%5B%22%E5%90%84%E9%93%B6%E8%A1%8C%E8%87%AA%E8%A1%8C%E6%B6%88%E5%8C%96%22%5D%0A%20%20L1%20--%3E%7C%22%E5%8E%8B%E5%8A%9B%E9%9B%86%E4%B8%AD%22%7C%20L2%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%3A%20%E6%B8%85%E7%AE%97%E7%BD%91%E7%BB%9C%E6%89%B9%E9%87%8F%E8%BD%A7%E8%B4%A6%22%5D%0A%20%20L2%20--%3E%7C%22%E4%BD%99%E9%A2%9D%E5%8F%AF%E8%BD%A7%E6%B8%85%22%7C%20ABS%0A%20%20L2%20--%3E%7C%22%E5%85%A8%E7%BD%91%E5%82%A8%E5%A4%87%E5%91%8A%E6%80%A5%22%7C%20L3%5B%22%E7%AC%AC%E4%B8%89%E5%B1%82%3A%20%E5%81%9C%E5%85%91%E9%98%80%E9%97%A8%22%5D%0A%20%20L3%20--%3E%20SUSP%5B%221837%20%E4%B8%8E%201857%3A%20%E5%85%A8%E9%9D%A2%E6%9A%82%E5%81%9C%E5%85%91%E4%BB%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p>不这么做会错在哪：把纪律寄托在发钞银行的声誉上，就解释不了边远地区折价长期偏大——声誉只覆盖监督得到的地方；把破产全归咎过发，就重演了野猫叙事对债券贬值的误诊。合约设计（期权条款）能删除挤兑均衡，但它保护的是兑付时点，不保护资不抵债。</p><p><span class="marginnote">常见误区：初学者容易以为自由银行等于「想怎么印就怎么印」，实际上约束从四面八方来——持有人天天回兑、清算网络可以拒绝你的券进入交换、存押的担保品还可能自己跌价。样本里银行破产的大头不是乱印，而是担保品贬值：看自由银行要看约束是否真实，不看名义上有没有监管。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评价自由银行是否整体优于央行制：苏格兰样本小、仍在金面额约束之下，美国样本又混着债券存押这种自设的担保品扭曲，对照要小心归因。国家券取代私人券的历史（美国的国民银行券与对州券征税）留给第七课。停兑时的政府介入算不算「最早的最后贷款人实践」，已有<a href="/econ/bm-lender-of-last-resort">最后贷款人</a>一课专论，此处不展开。</p><p>后课默认：谈「可兑换」三个字，要能说出兑换由谁执行、折价由谁发现、挤兑由哪一条款吸收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>银行券的平价不是法令给的，是回兑套利加清算网络每天重新挣出来的。</li><li>券的折价是发行行信用利差的实时报价；清算把检验成本压到套利可行。</li><li>野猫叙事被数据修正：债券存押贬值解释的破产远多于跑路。</li><li>期权条款把挤兑时点成本写进合同，是删除坏均衡的民间方案。</li><li>出处：Smith 1776；Selgin 1988；Rolnick and Weber 1983；Dowd 1992。</li></ul>',7))])}const _=l(C,[["render",p]]);export{u as __pageData,_ as default};
